:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e8e8f0;
  --green: #2ecc71;
  --red: #e74c3c;
  --yellow: #f1c40f;
  --blue: #3498db;
  --accent: #9b59b6;
  --focus: #ffd700;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  margin: 0 0 8px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.level-display {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 8px 0;
  color: var(--accent);
}

.status {
  min-height: 1.5em;
  margin: 8px 0 16px;
  font-size: 1rem;
  color: var(--text);
}

.pad-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 0 auto 20px;
  max-width: 320px;
}

.pad {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  opacity: 0.7;
  transition: opacity 0.15s, transform 0.1s, box-shadow 0.15s;
  outline: none;
}

.pad:hover:not(:disabled) { opacity: 0.9; }
.pad:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.pad:active:not(:disabled) { transform: scale(0.95); }
.pad.active {
  opacity: 1;
  box-shadow: 0 0 20px currentColor;
}

.pad-green { background: var(--green); color: var(--green); }
.pad-red { background: var(--red); color: var(--red); }
.pad-yellow { background: var(--yellow); color: var(--yellow); }
.pad-blue { background: var(--blue); color: var(--blue); }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover:not(:disabled) { background: #8e44ad; }
.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.btn:active:not(:disabled) { transform: scale(0.96); }
.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn-secondary { background: #555; }
.btn-secondary:hover:not(:disabled) { background: #666; }

@media (max-width: 400px) {
  .game-card { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .pad-grid { gap: 8px; max-width: 260px; }
  .btn { padding: 10px 18px; font-size: 0.95rem; }
}

(function () {
  'use strict';

  var pads = Array.prototype.slice.call(document.querySelectorAll('.pad'));
  var levelDisplay = document.getElementById('level-display');
  var statusEl = document.getElementById('status');
  var startBtn = document.getElementById('start-btn');
  var restartBtn = document.getElementById('restart-btn');

  var sequence = [];
  var playerIndex = 0;
  var level = 0;
  var acceptingInput = false;
  var playing = false;
  var timers = [];

  function clearTimers() {
    timers.forEach(function (t) { clearTimeout(t); });
    timers = [];
  }

  function setStatus(msg) { statusEl.textContent = msg; }

  function updateLevel() { levelDisplay.textContent = 'Level: ' + level; }

  function flashPad(index, duration) {
    var pad = pads[index];
    pad.classList.add('active');
    return new Promise(function (resolve) {
      var t = setTimeout(function () {
        pad.classList.remove('active');
        resolve();
      }, duration);
      timers.push(t);
    });
  }

  function playSequence() {
    acceptingInput = false;
    playing = true;
    setStatus('Watch the sequence...');
    var i = 0;

    function next() {
      if (i >= sequence.length) {
        playing = false;
        acceptingInput = true;
        playerIndex = 0;
        setStatus('Your turn!');
        return;
      }
      flashPad(sequence[i], 400).then(function () {
        i++;
        var t = setTimeout(next, 150);
        timers.push(t);
      });
    }
    next();
  }

  function nextRound() {
    level++;
    updateLevel();
    sequence.push(Math.floor(Math.random() * 4));
    playerIndex = 0;
    playSequence();
  }

  function gameOver() {
    acceptingInput = false;
    playing = false;
    clearTimers();
    pads.forEach(function (p) { p.classList.remove('active'); });
    setStatus('Game over');
    startBtn.disabled = true;
    restartBtn.disabled = false;
    restartBtn.focus();
  }

  function handlePad(index) {
    if (!acceptingInput) return;
    flashPad(index, 200);
    if (sequence[playerIndex] === index) {
      playerIndex++;
      if (playerIndex === sequence.length) {
        acceptingInput = false;
        setStatus('Good! Next level...');
        var t = setTimeout(nextRound, 800);
        timers.push(t);
      }
    } else {
      gameOver();
    }
  }

  function startGame() {
    clearTimers();
    sequence = [];
    playerIndex = 0;
    level = 0;
    acceptingInput = false;
    playing = false;
    pads.forEach(function (p) { p.classList.remove('active'); });
    startBtn.disabled = true;
    restartBtn.disabled = false;
    updateLevel();
    nextRound();
  }

  function restartGame() {
    startGame();
  }

  pads.forEach(function (pad) {
    pad.addEventListener('click', function () {
      handlePad(parseInt(pad.getAttribute('data-pad'), 10));
    });
  });

  startBtn.addEventListener('click', startGame);
  restartBtn.addEventListener('click', restartGame);

  updateLevel();
  setStatus('Press Start to play');
})();
